customer_retention_rate AS (\n        SELECT \n            o.store_id,\n            COUNT(DISTINCT CASE WHEN c.customer_id IN (\n                SELECT \n                    customer_id\n                FROM \n                    orders\n                WHERE \n                    store_id = o.store_id\n                    AND EXTRACT(MONTH FROM order_date) = EXTRACT(MONTH FROM CURRENT_DATE) - 1\n                    AND EXTRACT(YEAR FROM order_date) = EXTRACT(YEAR FROM CURRENT_DATE)\n                GROUP BY \n                    customer_id\n                HAVING \n                    COUNT(*) > 1\n            ) THEN c.customer_id END) * 100.0 / COUNT(DISTINCT c.customer_id) AS retention_rate\n        FROM \n            (\n            SELECT \n                o.store_id,\n                o.customer_id,\n                COUNT(*) AS order_count\n            FROM \n                orders o\n            WHERE \n                o.delivery_status = 'Đã giao'\n                AND EXTRACT(MONTH FROM o.order_date) = EXTRACT(MONTH FROM CURRENT_DATE)\n                AND EXTRACT(YEAR FROM o.order_date) = EXTRACT(YEAR FROM CURRENT_DATE)\n            GROUP BY \n                o.store_id, o.customer_id\n            ) c\n        GROUP BY \n            o.store_id\n    ),\n    \n    -- Calculate top performer product\n    top_performer_product AS (\n        SELECT \n            o.store_id,\n            f.title,\n            SUM(od.quantity) AS total_quantity,\n            SUM(od.quantity * f.price) AS total_revenue\n        FROM \n            orders o\n        JOIN \n            order_detail od ON o.id = od.order_id\n        JOIN \n            food f ON od.food_id = f.id\n        WHERE \n            o.delivery_status = 'Đã giao'\n            AND EXTRACT(MONTH FROM o.order_date) = EXTRACT(MONTH FROM CURRENT_DATE)\n            AND EXTRACT(YEAR FROM o.order_date) = EXTRACT(YEAR FROM CURRENT_DATE)\n        GROUP BY \n            o.store_id, f.title\n        ORDER BY \n            tot