0c1a43cc-4da5-4472-9072-5ad28c5458fe	65fea489-86b7-4f9f-99da-2ff276176a44	user	WITH StoreMetrics AS (\n    -- Bước 1: Tính toán tổng số đơn thành công, tổng doanh thu và AOV cho từng cửa hàng\n    SELECT\n        s.id AS store_id,\n        s.store_name,\n        COUNT(o.id) AS total_successful_orders,\n        -- Sử dụng kiểu numeric kết hợp ROUND(,0) để đảm bảo quy tắc Half Round Up\n        ROUND(SUM(o.total_after_discount)::numeric, 0) AS total_revenue,\n        ROUND((SUM(o.total_after_discount) / COUNT(o.id))::numeric, 0) AS avg_order_value\n    FROM\n        stores s\n    JOIN\n        orders o ON s.id = o.store_id\n    WHERE\n        o.order_status = 'Đã giao' -- Chỉ thống kê các đơn hàng giao thành công\n    GROUP BY\n        s.id, s.store_name\n),\nItemSalesRanking AS (\n    -- Bước 2: Tính tổng số lượng bán ra của từng món ăn tại mỗi cửa hàng và xếp hạng\n    SELECT\n        o.store_id,\n        f.title AS food_name,\n        SUM(od.quantity) AS total_quantity_sold,\n        -- Dùng Window Function để tìm món bán chạy nhất (Rank = 1) của từng store\n        RANK() OVER(\n            PARTITION BY o.store_id \n            ORDER BY SUM(od.quantity) DESC\n        ) as sales_rank\n    FROM\n        orders o\n    JOIN\n        order_detail od ON o.id = od.order_id\n    JOIN\n        food f ON od.food_id = f.id\n    WHERE\n        o.order_status = 'Đã giao'\n    GROUP BY\n        o.store_id, f.id, f.title\n)\n-- Bước 3: Gộp dữ liệu tổng quan của cửa hàng với món ăn bán chạy nhất của họ\nSELECT\n    sm.store_name,\n    sm.total_successful_orders,\n    sm.total_revenue,\n    sm.avg_order_value,\n    isr.food_name AS top_selling_item,\n    isr.total_quantity_sold AS top_item_quantity\nFROM\n    StoreMetrics sm\nLEFT JOIN\n    ItemSalesRanking isr ON sm.store_id = isr.store_id AND isr.sales_rank = 1\nORDER BY\n    sm.total_revenue DESC;	\N	2026-06-18 19:41:57.585566+07	chat	\N
